    bool ReadBool() { unsigned char v = 0; Read(&v, 1); return v != 0; }
    int ReadLong() { int v = 0; Read(&v, 4); return v; }
    u64 ReadULong64() { u64 v = 0; Read(&v, 8); return v; }
