struct CCharStringVector { CCharString* _M_start; CCharString* _M_finish; CCharString* _M_end_of_storage; };
struct CScriptDef {
    unsigned char _pad[0x9ac];
    CCharStringVector EscortBanditTypes;                // +0x9ac (descriptive name)
};
extern CScriptDef* g_pScriptDef;                        // 0x0143E90C
struct CQR_EscortTraderScript {
    unsigned char _pad[0x50];
    bool          TraderFollowing;                      // +0x50 (PDB +0x64)
};
struct CM_BanditTrigger {
    void* VTable; GameCalls* Game; CScriptThing Me;     // +0x00 / +0x04 / +0x08
    CQR_EscortTraderScript* ParentClass;                // +0x14
    void* PMasterData;                                  // +0x18
    bool BanditTriggered;                               // +0x1c
    void SetPredicate(const NScript::CPredicateBase&);  // 0x00F35B10
    bool IsActiveThreadTerminating();                   // 0x00F35B30
    void Main();
};

void CM_BanditTrigger::Main()
{
    SetPredicate(NScript::CIsThingAlive(Me));
    Game->NewScriptFrame();
    if (IsActiveThreadTerminating()) return;
    if (!ParentClass->TraderFollowing) return;
    if (BanditTriggered) return;
    if (IsActiveThreadTerminating()) return;
    CScriptThing spawnPoint;
    CCharString spawnName = Me.GetDataString();
    spawnPoint = Game->GetThingWithScriptName(spawnName);
    C3DVector pos = spawnPoint.GetPos();
    while (!IsDistanceBetweenThingsUnder(Game->GetHero(), Me, 5.0f)) {
        Game->NewScriptFrame();
        if (IsActiveThreadTerminating()) return;
    }
    if (IsActiveThreadTerminating()) return;
    if (IsActiveThreadTerminating()) return;
    for (;;) {
        while (Game->IsCameraPosOnScreen(pos)) {
            Game->NewScriptFrame();
            if (IsActiveThreadTerminating()) return;
        }
        if (IsActiveThreadTerminating()) return;
        {
            CTimer timer;
            timer.SetTime(3);
            while (Game->IsCameraPosOnScreen(pos) && timer.GetTime() != 0) {
                Game->NewScriptFrame();
                if (IsActiveThreadTerminating()) return;
            }
            if (IsActiveThreadTerminating()) return;
            if (!Game->IsCameraPosOnScreen(pos)) {
                if (IsActiveThreadTerminating()) return;
                break;
            }
        }
        Game->NewScriptFrame();
        if (IsActiveThreadTerminating()) return;
    }
    if (IsActiveThreadTerminating()) return;
    long count = g_pScriptDef->EscortBanditTypes._M_finish - g_pScriptDef->EscortBanditTypes._M_start;
    CCharString banditType = g_pScriptDef->EscortBanditTypes._M_start[rand() % count];
    CScriptThing bandit = Game->CreateCreature(banditType, pos, "AttackingBandit", false);
    if (spawnPoint.GetDataString() != "" && spawnPoint.GetDataString() != "NULL") {
        if (IsActiveThreadTerminating()) return;
        Game->AddItemToContainer(bandit, spawnPoint.GetDataString());
    }
    BanditTriggered = true;
    Game->RemoveThing(Me, false, true);
}

